const now = new Date();
const fmt = d => [String(d.getDate()).padStart(2,'0'), String(d.getMonth()+1).padStart(2,'0'), d.getFullYear()].join('/');
const p = new Date(now); p.setDate(now.getDate() - 2);
const f = new Date(now); f.setDate(now.getDate() + 30);
return [{ json: { dtInicio: fmt(p), dtFim: fmt(f), executado_em: now.toISOString() } }];

