const out = [];
const norm = a => {
  const p = (a.dtAgenda || '').split('/');
  const d = p.length === 3 ? p[2] + '-' + p[1] + '-' + p[0] : null;
  const h = d && a.hrConsulta ? new Date(d + 'T' + a.hrConsulta + ':00').toISOString() : null;
  return { json: {
    belle_id:          a.codConsulta,
    belle_cliente_cod: String(a.cliente?.cod || ''),
    nome_cliente:      (a.cliente?.nome || '').replace(/'/g, "''"),
    celular_cliente:   a.cliente?.celular || '',
    cod_profissional:  String(a.prof?.cod || ''),
    nome_profissional: (a.prof?.nome || '').replace(/'/g, "''"),
    nome_sala:         a.sala?.nome || '',
    servicos:          JSON.stringify(a.servicos || []),
    dt_agenda: d, hr_consulta: a.hrConsulta || '', data_hora: h,
    status: a.status || '', tipo: a.status || '',
    observacao: (a.observacao || '').replace(/'/g, "''"),
  }};
};
for (const item of $input.all()) {
  const data = item.json;
  const rows = Array.isArray(data) ? data : (data.codConsulta ? [data] : []);
  for (const a of rows) { if (a.codConsulta) out.push(norm(a)); }
}
console.log('Normalizados: ' + out.length);
return out;

