const item = $input.item.json;
if (!item.id) return null;
const stageMap = {
  'Marcado':   '711be8cc-a0cb-4bcb-ae40-428f1ad47873',
  'Atendido':  'f09cdbdb-fb8e-4f04-b5f8-4a20a8de3341',
  'Cancelado': '455aafb0-8fef-45d6-beb4-41888cc7d18a',
};
const stage_id = stageMap[item.status] || stageMap['Marcado'];
let servicos_label = '';
try {
  const raw = item.servicos;
  const arr = typeof raw === 'string' ? JSON.parse(raw || '[]') : (Array.isArray(raw) ? raw : []);
  servicos_label = arr.map(s => (typeof s === 'string' ? s : String(s.nome || '')).trim()).filter(Boolean).join(', ');
} catch(e) {}
if (!servicos_label) servicos_label = 'Avaliação';
const nome_profissional = (item.nome_profissional || '').trim();
const dt_agenda_fmt = item.dt_agenda ? item.dt_agenda.substring(0,10).split('-').reverse().join('/') : '';
return { json: { ...item, stage_id, nome_profissional, dt_agenda_fmt, card_name: item.nome_cliente.trim(), servicos_label } };

